auto maxHeapify = [](auto self, int arr[], int size, int i) -> void {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < size && arr[left] > arr[largest]) {
        largest = left;
    }

    if (right < size && arr[right] > arr[largest]) {
        largest = right;
    }

    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        self(self, arr, size, largest);
    }
};

for (int i = size / 2 - 1; i >= 0; i--) {
    maxHeapify(maxHeapify, arr, size, i);
}

